using FamilyVeda.Domain.Common;
using FamilyVeda.Application.Common;

namespace FamilyVeda.Application.Auth;

public sealed record RegisterRequest(string Email, string Password, string DisplayName, UserType UserType, string? Nic = null, string? Address = null);
public sealed record LoginRequest(string Email, string Password);
public sealed record RefreshRequest(string RefreshToken);
public sealed record AuthResponse(Guid UserId, string DisplayName, UserType UserType, FamilyRole? FamilyRole, VerificationStatus? DoctorVerificationStatus, string AccessToken, string RefreshToken, DateTimeOffset AccessTokenExpiresAt, VerificationStatus? FamilyHeadVerificationStatus = null, string? FamilyCode = null);

public sealed record ForgotPasswordRequest(string Email);
public sealed record ResetPasswordRequest(string Email, string Token, string NewPassword);
public sealed record ChangePasswordRequest(string CurrentPassword, string NewPassword);
public sealed record AdminResetPasswordRequest(string? Reason = null);
public sealed record AdminToggleStatusRequest(bool IsActive, string? Reason = null);
public sealed record ResetPasswordResponse(bool Success, string Message, string? ResetToken = null);
public sealed record AdminUserDto(Guid UserId, string Email, string DisplayName, UserType UserType, bool IsActive, DateTimeOffset CreatedAt, string? Status = null, string? RoleDetail = null);

public interface IAuthService
{
    Task<AuthResponse> RegisterAsync(RegisterRequest request, CancellationToken cancellationToken);
    Task<AuthResponse> LoginAsync(LoginRequest request, CancellationToken cancellationToken);
    Task<AuthResponse> RefreshAsync(RefreshRequest request, CancellationToken cancellationToken);
    Task LogoutAsync(CancellationToken cancellationToken);
    Task<ResetPasswordResponse> ForgotPasswordAsync(ForgotPasswordRequest request, CancellationToken cancellationToken);
    Task<ResetPasswordResponse> ResetPasswordAsync(ResetPasswordRequest request, CancellationToken cancellationToken);
    Task ChangePasswordAsync(ChangePasswordRequest request, CancellationToken cancellationToken);
    Task<PagedResult<AdminUserDto>> GetAdminUsersAsync(int page, int pageSize, string? search, CancellationToken cancellationToken);
    Task<ResetPasswordResponse> AdminResetPasswordAsync(Guid userId, AdminResetPasswordRequest request, CancellationToken cancellationToken);
    Task<AdminUserDto> AdminToggleUserStatusAsync(Guid userId, AdminToggleStatusRequest request, CancellationToken cancellationToken);
}
